import {printers,choosePrinter,getPrinter,navigationURL} from './printers.js?v=printer-cards-2';
const deliveryFee='US$'+((window.PopomoOrders?.deliveryShippingCents??400)/100).toFixed(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fulfillmentReady(f){return f?.method==='pickup'?!!getPrinter(f.deviceId):f?.method==='delivery'&&f.addressSaved!==false&&!!(f.address?.recipient&&f.address?.phone&&f.address?.region&&f.address?.street);}
export function fulfillmentLabel(f,en=false){return f?.method==='delivery'?(en?'Mail delivery':'快递邮寄'):f?.method==='pickup'?(en?'Device printing':'设备打印'):(en?'Choose fulfillment':'待选择领取方式');}
export function mountFulfillment(root,{value={},onSave,locked=false,readOnly=false}={}){let state=structuredClone(value||{}),lang=document.documentElement.lang.startsWith('en');const t=(zh,en)=>lang?en:zh;function save(refresh=false){if(readOnly||locked)return;onSave(structuredClone(state),{refresh});}function render(){const p=state.device||getPrinter(state.deviceId),a=state.address||{};if(readOnly){root.innerHTML=readonlySummary(state,p,a,t);return;}root.innerHTML=`<section class="fulfillment-panel"><h2>${t('选择领取方式','Choose how to receive your case')}</h2><div class="fulfillment-options" role="group" aria-label="${t('领取方式','Fulfillment method')}"><button data-method="pickup" aria-pressed="${state.method==='pickup'}" ${locked?'disabled':''}><span aria-hidden="true">⌖</span><strong>${t('就近打印','Nearby printing')}</strong><small>${t('选择设备，到店打印','Choose a device and print on site')}</small></button><button data-method="delivery" aria-pressed="${state.method==='delivery'}" ${locked?'disabled':''}><span aria-hidden="true">▱</span><strong>${t('快递到家','Ship to home')}</strong><small>${t('运费 '+deliveryFee+' · 预计 3–4 天送达',deliveryFee+' shipping · 3–4 days')}</small></button></div>${state.method==='pickup'?`<div class="fulfillment-device">${p?`<strong>${esc(p.name)}</strong><p>${esc(p.address)}</p><small>${p.lat}, ${p.lng}</small><div>${printers.length>1?`<button class="tertiary" data-pick ${locked?'disabled':''}>${t('更换设备','Change printer')}</button>`:''}<a class="secondary" href="${navigationURL(p)}" target="_blank" rel="noopener noreferrer">${t('地图导航','Directions')} ↗</a></div>`:`<p>${t('先选择方便前往的纽约设备，定位后优先显示最近的点位。','Choose a New York printer. Enable location to find the nearest one.')}</p><button class="secondary" data-pick ${locked?'disabled':''}>${t('定位并选择设备','Find a nearby printer')} ↗</button>`}</div>`:state.method==='delivery'?`<p class="delivery-estimate">${t('运费 '+deliveryFee+'，预计 3–4 天送达。',deliveryFee+' shipping. Estimated delivery: 3–4 days.')}</p><form class="delivery-address"><div class="address-pair"><label>${t('收件人','Recipient')}<input name="recipient" autocomplete="shipping name" maxlength="60" required value="${esc(a.recipient||'')}" ${locked?'disabled':''}></label><label>${t('联系电话','Phone')}<input name="phone" type="tel" autocomplete="shipping tel" minlength="6" maxlength="24" required value="${esc(a.phone||'')}" ${locked?'disabled':''}></label></div><label>${t('国家 / 州 / 城市','Country / state / city')}<input name="region" autocomplete="shipping address-level1" maxlength="150" required placeholder="United States / NY / New York" value="${esc(a.region||'')}" ${locked?'disabled':''}></label><label>${t('详细地址','Street address')}<input name="street" autocomplete="shipping street-address" maxlength="250" required placeholder="Street, building, apartment" value="${esc(a.street||'')}" ${locked?'disabled':''}></label><label>${t('邮政编码（选填）','Postal code (optional)')}<input name="postal" autocomplete="shipping postal-code" maxlength="20" value="${esc(a.postal||'')}" ${locked?'disabled':''}></label><button class="secondary" type="submit" ${locked?'disabled':''}>${t('保存收货地址','Save address')}</button><p class="address-status" role="status">${fulfillmentReady(state)?t('收货地址已保存','Delivery address saved'):''}</p></form>`:`<p class="fulfillment-hint">${t('请选择就近打印或快递到家后继续。','Choose nearby printing or delivery to continue.')}</p>`}<p class="fulfillment-error" role="alert"></p></section>`;root.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{state.method=b.dataset.method;if(state.method==='delivery')state.deliveryDays='3–4';save(true);render();});root.querySelector('[data-pick]')?.addEventListener('click',()=>choosePrinter({selectedId:state.deviceId,onSelect:p=>{state.deviceId=p.id;save(true);render();}}));root.querySelector('.delivery-address')?.addEventListener('input',()=>{state.addressSaved=false;root.querySelector('.address-status').textContent=t('地址有变更，请保存后继续。','Address changed. Save to continue.');save();});root.querySelector('.delivery-address')?.addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(values))values[key]=values[key].trim();if(!values.recipient||!values.phone||!values.region||!values.street){root.querySelector('.fulfillment-error').textContent=t('请填写完整收货信息。','Complete your delivery address.');return;}state.address=values;state.addressSaved=true;save(true);render();});}render();}

function readonlySummary(state,p,a,t){const row=(label,value)=>`<div><dt>${label}</dt><dd>${esc(value||'—')}</dd></div>`;return `<section class="fulfillment-panel fulfillment-readonly"><h2>${t('领取方式','Fulfillment method')}</h2><span class="fulfillment-tag ${state.method==='delivery'?'is-delivery':'is-device'}">${fulfillmentLabel(state,document.documentElement.lang.startsWith('en'))}</span>${state.method==='pickup'?`<div class="fulfillment-device">${p?`<strong>${esc(p.name)}</strong><p>${esc(p.address)}</p><a class="secondary" href="${navigationURL(p)}" target="_blank" rel="noopener noreferrer">${t('导航到设备','Directions to printer')} ↗</a>`:`<p>${t('此订单未记录设备信息。','No printer information was recorded for this order.')}</p>`}</div>`:state.method==='delivery'?`<p class="delivery-estimate">${t('预计 3–4 天送达。','Estimated delivery: 3–4 days.')}</p><dl class="fulfillment-address-summary">${row(t('收件人','Recipient'),a.recipient)}${row(t('联系电话','Phone'),a.phone)}${row(t('收货区域','Region'),a.region)}${row(t('详细地址','Street address'),a.street)}${a.postal?row(t('邮政编码','Postal code'),a.postal):''}</dl>`:`<p class="fulfillment-hint">${t('此订单未记录领取信息。','No fulfillment information was recorded for this order.')}</p>`}</section>`;}
